impl MessageCode {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match TABLE.iter().find(|row| row.0 == self) {
            Some(row) => row.1,
            None => "unknown",
        }
    }
}

impl MessageCode {
    #[must_use]
    pub fn from_code(text: &str) -> Option<Self> {
        TABLE.iter().find(|row| row.1 == text).map(|row| row.0)
    }
    #[must_use]
    pub fn all() -> Vec<Self> {
        TABLE.iter().map(|row| row.0).collect()
    }
}

impl crate::catalog::MessageCodeLike for MessageCode {
    fn as_str(&self) -> &str {
        MessageCode::as_str(*self)
    }
}
